// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address user) public {
        // 1. Admissible domain: user must not be the zero address, and amounts must be non-zero but reasonable
        vm.assume(user != address(0));
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        withdrawAmount = bound(withdrawAmount, 1, depositAmount);

        // 2. Scenario setup and driving c through withdrawAll
        // First, deposit some funds as a different user to give the contract balance
        address funder = address(0x10000);
        vm.deal(funder, depositAmount);
        vm.prank(funder);
        c.deposit{value: depositAmount}();

        // Record contract's state before the user's actions
        uint256 contractBalanceBefore = address(c).balance;

        // The user deposits and then attempts to withdraw all
        vm.deal(user, depositAmount);
        vm.prank(user);
        c.deposit{value: depositAmount}();

        // The user now attempts withdrawal. We wrap the call to detect revert.
        vm.prank(user);
        bool withdrawReverted = false;
        try c.withdrawAll() {
            // No revert
        } catch {
            withdrawReverted = true;
        }

        // 3. Assertion: After the transaction, if the withdraw did not revert, the contract balance
        // plus the sum of all known credits must equal the internal 'balance' variable.
        // We read credits indirectly by computing the expected balance.
        // The internal 'balance' variable is public (auto-generated getter).
        uint256 internalBalance = c.balance();
        // The contract's actual ether balance
        uint256 etherBalance = address(c).balance;
        // We need to account for credits that were not withdrawn. The funder's credit is still inside.
        // The user's credit was either withdrawn (if call succeeded) or reduced to 0.
        // We can compute total outstanding credits as: internalBalance = sum of all credits.
        // The invariant is: internalBalance == etherBalance + pendingCreditsOut (which is 0 here).
        // Actually, since all credits are always recorded in the internal balance, and ether can only leave
        // via successful calls, the invariant should be: etherBalance == internalBalance.
        // Let's verify: The bug version can decrease internalBalance without sending ether.
        assertTrue(etherBalance == internalBalance);
    }
}

