pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 actorSeed) public {
        // Restrict deposit amount to a reasonable range and actorSeed to generate a deterministic address
        vm.assume(depositAmount > 0 && depositAmount < 1000 ether);
        address actor = address(uint160(uint256(keccak256(abi.encode(actorSeed)))));
        vm.assume(actor != address(0) && actor != address(this) && actor != address(c));

        // Give the actor ether and have them deposit into the contract
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        // Record the contract's ETH balance before the withdraw attempt
        uint256 contractEthBefore = address(c).balance;

        // Deploy a malicious actor that reverts on receive
        RevertingReceiver reverting = new RevertingReceiver();
        // Transfer the deposit credit to the reverting receiver by having the original actor deposit,
        // but we need the reverting receiver to have the credit. We'll make the reverting receiver
        // receive the deposit amount from the original actor via an internal transfer approach.
        // Instead, we directly prank as the reverting receiver and deposit to get credit.
        // Reset: we want the reverting receiver to have credit, so let's start fresh with it.
        vm.deal(address(reverting), depositAmount);
        vm.prank(address(reverting));
        c.deposit{value: depositAmount}();

        uint256 contractEthBeforeWithdraw = address(c).balance;

        // Now attempt withdrawAll as the reverting receiver
        bool callSucceeded;
        try c.withdrawAll() { callSucceeded = true; } catch { callSucceeded = false; }

        // After the withdrawAll call, the contract's ETH balance must equal the balance before the call
        // if the call reverted, and must be decreased if it succeeded. Since the receiver reverts,
        // the correct contract reverts entirely (callSucceeded false) and balance unchanged.
        // The mutant updates internal state without reverting, but ETH isn't sent, leaving ETH balance unchanged
        // while internal balance decreases. The invariant: if callSucceeded is false, contract ETH balance must
        // remain the same; the mutant violates this by decreasing internal accounting.
        // But we read surface: we can check that after revert, the receiver's credit is still nonzero (correct)
        // vs zero (mutant). The invariant: after a reverting withdraw, credit must not change.
        assertTrue(callSucceeded == false ? c.credit(address(reverting)) == depositAmount : true);
    }
}

contract RevertingReceiver {
    receive() external payable {
        revert("revert on receive");
    }
}

