pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint96 depositAmt, uint96 withdrawAttempt) public {
        vm.assume(caller != address(0) && caller != address(c));
        // Set up: caller deposits some Ether
        vm.deal(caller, uint256(depositAmt) + 1 ether);
        vm.prank(caller);
        c.deposit{value: depositAmt}();
        // Ensure caller's credit is zero before the test withdraw (so withdrawAttempt=0 means zero credit)
        // We want a scenario where credit[caller] == 0.
        // If depositAmt > 0, we can first withdraw all to set credit to 0, then we have zero credit.
        if (depositAmt > 0) {
            vm.prank(caller);
            c.withdrawAll();
        }
        // Now credit[caller] is definitely 0.
        uint256 ethBefore = address(c).balance;
        bool success;
        vm.prank(caller);
        try c.withdrawAll() { success = true; } catch { success = false; }
        uint256 ethAfter = address(c).balance;
        // If the call did not revert, credit must be 0 and if initial credit was 0, ETH balance unchanged.
        // Since we know credit[caller] == 0 before the call, the ETH balance must remain the same on success.
        // The reference contract skips the block when credit==0 (oCredit>0 false) and does nothing, so no revert, balance unchanged.
        // The mutant enters the block, subtracts 0, sets credit=0, and makes a 0-value call which can consume gas and potentially change the balance.
        assertTrue(!success || ethAfter == ethBefore);
    }
}
